#define _XOPEN_SOURCE_EXTENDED 1
#include <locale.h>
#include <wchar.h>
#include <string.h>
#include <ncursesw/curses.h>
int main(int argc,char**argv){
 setlocale(LC_ALL,"");
 initscr(); start_color(); use_default_colors();
 int vals[] = {0xA6,0xC0,0xD0,0xFF,0xFF66,0xFF7F,0xFF80,0xFF9C,0x30A6,0x30C3,0x2191,0x2517,0};
 int mode = argv[1][0];
 for(int r=0; vals[r]; r++){
   int v=vals[r];
   int y=r; int x=0;
   if(mode=='a') mvaddch(y,x,v);
   else if(mode=='b') mvaddch(y,x,v|A_ALTCHARSET);
   else if(mode=='c'){ wchar_t w=v; cchar_t cc; setcchar(&cc,&w,0,0,NULL); mvadd_wch(y,x,&cc); }
   else if(mode=='d') mvprintw(y,x,"%lc",(wint_t)v);
   else if(mode=='e') mvaddch(y,x,(unsigned char)v);
   else if(mode=='f'){ // addstr of utf8? skip
     mvaddch(y,x,v);
   }
   // marker at col 20
   mvaddch(y,20,'|');
   mvprintw(y,22,"%x",v);
 }
 refresh(); getch(); endwin(); return 0;
}
