{"command":"cat > cmatrix.c << 'EOF'
/*
 * cmatrix - scrolling "Matrix" like display for a terminal.
 *
 * Original code written from scratch for this project.  The program
 * draws falling columns of characters on a curses screen, with a
 * bright head and a coloured trail, much like the digital rain seen
 * in the films.
 */

#define _XOPEN_SOURCE_EXTENDED 1

#include <ctype.h>
#include <errno.h>
#include <locale.h>
#include <ncursesw/curses.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <time.h>
#include <unistd.h>
#include <wchar.h>

/* Bold modes.  B_SPECIAL is the peculiar mode selected from the
 * command line by -n: trails are never bold, but heads still are. */
enum {
    BOLD_DEFAULT = 0,
    BOLD_RANDOM = 1,
    BOLD_ALL = 2,
    BOLD_SPECIAL = 3
};

/* Cell states (new style). */
enum {
    CELL_BLANK = 0,
    CELL_HEAD = 1,
    CELL_TRAIL = 2
};

/* Extra states only used by the old scrolling style. */
enum {
    CELL_OLD_HEAD = 3,
    CELL_OLD_SECOND = 4
};

#define PAIR_TRAIL 1
#define PAIR_HEAD 2
#define PAIR_RAINBOW_BASE 3

#define LAMBDA_CODEPOINT 0x03bb
#define X_HEAD_CODEPOINT 0xa6

typedef struct {
    int code;        /* generated character code for this cell */
    int stream_len;  /* lifetime (in rows) of the stream it belongs to */
    int age;
    int state;
    int rand_bold;
} Cell;

typedef struct {
    int spawn_timer;
    int async_rate;
    /* old style generator state */
    int old_state;   /* 0 = spaces, 1 = active */
    int old_timer;
    int old_pos;
} Column;

static int rows = 0;
static int cols = 0;
static int ncols = 0;
static Cell *cells = NULL;
static Column *columns = NULL;

static int update_delay = 4;
static int bold = BOLD_DEFAULT;
static int mcolour = COLOR_GREEN;
static int trail_pair = PAIR_TRAIL;

static bool async_scroll = false;
static bool old_style = false;
static bool japanese = false;
static bool xwindow = false;
static bool lambda_mode = false;
static bool rainbow = false;
static bool char_change = false;
static bool screensaver = false;
static bool lock_mode = false;
static bool linux_mode = false;
static bool force_linux = false;
static bool paused_now = false;

static const char *message = NULL;
static const char *tty_name = NULL;
static FILE *tty_fp = NULL;

static bool curses_started = false;
static volatile sig_atomic_t stop_requested = 0;

static void print_usage(void)
{
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n"
           " -a: Asynchronous scroll\n"
           " -b: Bold characters on\n"
           " -B: All bold characters (overrides -b)\n"
           " -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n"
           " -f: Force the linux $TERM type to be on\n"
           " -l: Linux mode (uses matrix console font)\n"
           " -L: Lock mode (can be closed from another terminal)\n"
           " -o: Use old-style scrolling\n"
           " -h: Print usage and exit\n"
           " -n: No bold characters (overrides -b and -B, default)\n"
           " -s: \"Screensaver\" mode, exits on first keystroke\n"
           " -x: X window mode, use if your xterm is using mtx.pcf\n"
           " -V: Print version information and exit\n"
           " -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n"
           " -u delay (0 - 10, default 4): Screen update delay\n"
           " -C [color]: Use this color for matrix (default green)\n"
           " -r: rainbow mode\n"
           " -m: lambda mode\n"
           " -k: Characters change while scrolling. (Works without -o opt.)\n"
           " -t [tty]: Set tty to use\n");
}

static void print_version(void)
{
    printf(" CMatrix version 2.0 (compiled 22:13:51, Jun 11 2026)\n"
           "Email: abishekvashok@gmail.com\n"
           "Web: https://github.com/abishekvashok/cmatrix\n");
}

static void finish(int status)
{
    if (curses_started) {
        endwin();
        curses_started = false;
    }
    exit(status);
}

/* SIGTERM terminates right away with a failure status, like the
 * reference program's handler. */
static void term_handler(int sig)
{
    (void)sig;
    if (curses_started)
        endwin();
    exit(1);
}

static void stop_handler(int sig)
{
    (void)sig;
    stop_requested = 1;
}

static int draw_spaces(void)
{
    if (rows > 0)
        return 2 + (rand() % rows);
    return 2;
}

static int draw_length(void)
{
    int range = rows - 3;
    if (range < 1)
        range = 1;
    return 4 + (rand() % range);
}

static int generate_code(void)
{
    if (japanese)
        return 0xff66 + (rand() % 55);
    if (xwindow)
        return 0xa6 + (rand() % 51);
    return 33 + (rand() % 90);
}

static void set_colour(int colour)
{
    mcolour = colour;
    if (colour == COLOR_BLACK) {
        /* Colour zero is curses' default pair: nothing to init. */
        trail_pair = 0;
    } else {
        init_pair(PAIR_TRAIL, colour, -1);
        trail_pair = PAIR_TRAIL;
    }
}

static int rainbow_pair(void)
{
    static const int rainbow_pairs[5] = {
        PAIR_RAINBOW_BASE,     /* green */
        PAIR_RAINBOW_BASE + 1, /* yellow */
        PAIR_RAINBOW_BASE + 2, /* blue */
        PAIR_RAINBOW_BASE + 3, /* magenta */
        PAIR_RAINBOW_BASE + 4  /* cyan */
    };
    int r = rand() % 6;
    if (r == 0)
        return 0;
    return rainbow_pairs[r - 1];
}

static bool head_bold(void)
{
    return bold != BOLD_DEFAULT;
}

static bool trail_bold(const Cell *cell)
{
    if (bold == BOLD_ALL)
        return true;
    if (bold == BOLD_RANDOM)
        return cell->rand_bold != 0;
    return false;
}

static void draw_wide_char(int y, int x, wchar_t wc, int pair, bool bold_attr)
{
    cchar_t cc;
    wchar_t ws[2];
    ws[0] = wc;
    ws[1] = L'\0';
    setcchar(&cc, ws, bold_attr ? A_BOLD : 0, (short)pair, NULL);
    mvadd_wch(y, x, &cc);
}

/* Draw a cell using its "mode" character (the trail character). */
static void draw_mode_char(int y, int x, const Cell *cell, int pair, bool bold_attr)
{
    if (lambda_mode) {
        draw_wide_char(y, x, (wchar_t)LAMBDA_CODEPOINT, pair, bold_attr);
    } else if (japanese) {
        draw_wide_char(y, x, (wchar_t)cell->code, pair, bold_attr);
    } else if (xwindow) {
        draw_wide_char(y, x, (wchar_t)cell->code, pair, bold_attr);
    } else {
        chtype ch = (chtype)(unsigned char)cell->code;
        if (bold_attr)
            ch |= A_BOLD;
        ch |= COLOR_PAIR(pair);
        mvaddch(y, x, ch);
    }
}

/* Draw a new-style head cell.  These use the plain curses addch
 * interface, which is why wide character codes in Japanese and X
 * modes show through as their low byte (with the familiar curses
 * control character rendering spilling onto the next column). */
static void draw_head_char(int y, int x, const Cell *cell)
{
    bool b = head_bold();
    if (japanese) {
        chtype ch = (chtype)(cell->code & 0xff);
        if (b)
            ch |= A_BOLD;
        ch |= COLOR_PAIR(trail_pair);
        mvaddch(y, x, ch);
    } else if (xwindow) {
        chtype ch = (chtype)(cell->code & 0xff);
        ch |= A_ALTCHARSET;
        if (b)
            ch |= A_BOLD;
        ch |= COLOR_PAIR(PAIR_HEAD);
        mvaddch(y, x, ch);
    } else {
        chtype ch = (chtype)(unsigned char)cell->code;
        if (b)
            ch |= A_BOLD;
        ch |= COLOR_PAIR(PAIR_HEAD);
        mvaddch(y, x, ch);
    }
}

static void free_matrix(void)
{
    free(cells);
    free(columns);
    cells = NULL;
    columns = NULL;
}

static void init_matrix(int new_rows, int new_cols)
{
    free_matrix();
    rows = new_rows;
    cols = new_cols;
    if (rows < 1)
        rows = 1;
    if (cols < 1)
        cols = 1;
    ncols = (cols + 1) / 2;
    cells = (Cell *)calloc((size_t)rows * (size_t)ncols, sizeof(Cell));
    columns = (Column *)calloc((size_t)ncols, sizeof(Column));
    if (cells == NULL || columns == NULL) {
        rows = 0;
        cols = 0;
        ncols = 0;
        return;
    }
    for (int i = 0; i < ncols; i++) {
        columns[i].spawn_timer = draw_spaces();
        columns[i].async_rate = 1 + (rand() % 3);
        columns[i].old_state = 0;
        columns[i].old_timer = draw_spaces();
        columns[i].old_pos = 0;
    }
}

/* ----- new style ----- */

static void new_column_tick(int ci)
{
    /* Remember where the heads were at the end of last frame. */
    bool heads[rows];
    /* (rows is a run time value; a VLA is fine here) */
    for (int y = 0; y < rows; y++)
        heads[y] = (cells[y * ncols + ci].state == CELL_HEAD);

    /* Age every live cell; expired cells go blank. */
    for (int y = 0; y < rows; y++) {
        Cell *cell = &cells[y * ncols + ci];
        if (cell->state != CELL_BLANK) {
            cell->age++;
            if (cell->age >= cell->stream_len) {
                memset(cell, 0, sizeof(*cell));
            }
        }
    }

    /* Advance each head by one row and turn it into trail. */
    for (int y = 0; y < rows; y++) {
        if (!heads[y])
            continue;
        Cell *cell = &cells[y * ncols + ci];
        if (cell->state == CELL_BLANK)
            continue;
        int len = cell->stream_len;
        cell->state = CELL_TRAIL;
        if (y + 1 < rows) {
            Cell *next = &cells[(y + 1) * ncols + ci];
            memset(next, 0, sizeof(*next));
            next->code = generate_code();
            next->stream_len = len;
            next->age = 0;
            next->state = CELL_HEAD;
            next->rand_bold = rand() % 2;
        }
    }

    /* Start a new stream at the top when the timer runs out. */
    Column *column = &columns[ci];
    column->spawn_timer--;
    if (column->spawn_timer <= 0) {
        int len = draw_length();
        Cell *cell = &cells[ci];
        memset(cell, 0, sizeof(*cell));
        cell->code = generate_code();
        cell->stream_len = len;
        cell->age = 0;
        cell->state = CELL_HEAD;
        cell->rand_bold = rand() % 2;
        column->spawn_timer = len + draw_spaces();
    }
}

static void update_new(unsigned long frame)
{
    if (cells == NULL)
        return;
    for (int ci = 0; ci < ncols; ci++) {
        if (async_scroll && ((frame % 3) >= (unsigned long)columns[ci].async_rate))
            continue;
        new_column_tick(ci);
    }
    if (char_change) {
        for (int i = 0; i < rows * ncols; i++) {
            if (cells[i].state == CELL_TRAIL && (rand() % 8) == 0) {
                cells[i].code = generate_code();
                cells[i].rand_bold = rand() % 2;
            }
        }
    }
}

static void draw_new(void)
{
    for (int y = 0; y < rows; y++) {
        for (int ci = 0; ci < ncols; ci++) {
            int x = ci * 2;
            Cell *cell = &cells[y * ncols + ci];
            if (cell->state == CELL_BLANK) {
                mvaddch(y, x, (chtype)(' ' ) | COLOR_PAIR(trail_pair));
            } else if (rainbow) {
                int pair = rainbow_pair();
                bool b = (cell->state == CELL_HEAD) ? head_bold() : trail_bold(cell);
                draw_mode_char(y, x, cell, pair, b);
            } else if (cell->state == CELL_HEAD) {
                draw_head_char(y, x, cell);
            } else {
                draw_mode_char(y, x, cell, trail_pair, trail_bold(cell));
            }
        }
    }
}

/* ----- old style ----- */

static void old_column_tick(int ci)
{
    /* Shift the whole column down by one cell. */
    for (int y = rows - 1; y > 0; y--)
        cells[y * ncols + ci] = cells[(y - 1) * ncols + ci];

    Column *column = &columns[ci];
    Cell *top = &cells[ci];
    memset(top, 0, sizeof(*top));

    if (column->old_state == 0) {
        /* Inactive phase: blank cells fall down the screen. */
        top->state = CELL_BLANK;
        column->old_timer--;
        if (column->old_timer <= 0) {
            column->old_state = 1;
            column->old_pos = 0;
        }
        return;
    }

    /* Active phase. */
    if (column->old_pos == 0) {
        top->state = CELL_OLD_HEAD;
    } else if (column->old_pos == 1) {
        top->state = CELL_OLD_SECOND;
        top->code = '|';
    } else {
        top->state = CELL_TRAIL;
        top->code = generate_code();
    }
    top->rand_bold = rand() % 2;
    column->old_pos++;
    if (column->old_pos > 2 && (rand() % 10) == 0) {
        column->old_state = 0;
        column->old_timer = draw_spaces();
    }
}

static void update_old(unsigned long frame)
{
    if (cells == NULL)
        return;
    for (int ci = 0; ci < ncols; ci++) {
        if (async_scroll && ((frame % 3) >= (unsigned long)columns[ci].async_rate))
            continue;
        old_column_tick(ci);
    }
}

static void draw_old(void)
{
    for (int y = 0; y < rows; y++) {
        for (int ci = 0; ci < ncols; ci++) {
            int x = ci * 2;
            Cell *cell = &cells[y * ncols + ci];
            if (cell->state == CELL_BLANK) {
                mvaddch(y, x, (chtype)(' ') | COLOR_PAIR(trail_pair));
            } else if (cell->state == CELL_OLD_HEAD) {
                bool b = head_bold();
                if (xwindow) {
                    chtype ch = (chtype)X_HEAD_CODEPOINT;
                    ch |= A_ALTCHARSET;
                    if (b)
                        ch |= A_BOLD;
                    ch |= COLOR_PAIR(PAIR_HEAD);
                    mvaddch(y, x, ch);
                } else {
                    chtype ch = (chtype)'&';
                    if (b)
                        ch |= A_BOLD;
                    ch |= COLOR_PAIR(PAIR_HEAD);
                    mvaddch(y, x, ch);
                }
            } else if (cell->state == CELL_OLD_SECOND) {
                int pair = rainbow ? rainbow_pair() : trail_pair;
                chtype ch = (chtype)'|';
                if (trail_bold(cell))
                    ch |= A_BOLD;
                ch |= COLOR_PAIR(pair);
                mvaddch(y, x, ch);
            } else {
                int pair = rainbow ? rainbow_pair() : trail_pair;
                draw_mode_char(y, x, cell, pair, trail_bold(cell));
            }
        }
    }
}

/* ----- message ----- */

static void draw_message(void)
{
    if (message == NULL)
        return;
    int len = (int)strlen(message);
    int y = rows / 2;
    int x = cols / 2 - len / 2 - 2;
    mvprintw(y, x, "  %s  ", message);
}

/* ----- input ----- */

static void handle_key(int ch)
{
    switch (ch) {
    case 'q':
        if (!lock_mode)
            finish(0);
        break;
    case 'a':
        async_scroll = !async_scroll;
        break;
    case 'b':
        bold = BOLD_RANDOM;
        break;
    case 'B':
        bold = BOLD_ALL;
        break;
    case 'n':
        bold = BOLD_DEFAULT;
        break;
    case '0': case '1': case '2': case '3': case '4':
    case '5': case '6': case '7': case '8': case '9':
        update_delay = ch - '0';
        break;
    case '!':
        rainbow = false; set_colour(COLOR_RED); break;
    case '@':
        rainbow = false; set_colour(COLOR_GREEN); break;
    case '#':
        rainbow = false; set_colour(COLOR_YELLOW); break;
    case '$':
        rainbow = false; set_colour(COLOR_BLUE); break;
    case '%':
        rainbow = false; set_colour(COLOR_MAGENTA); break;
    case '^':
        rainbow = false; set_colour(COLOR_CYAN); break;
    case '&':
        rainbow = false; set_colour(COLOR_WHITE); break;
    case 'p':
    case 'P':
        paused_now = !paused_now;
        break;
    case 'm':
        lambda_mode = !lambda_mode;
        break;
    case 'r':
        rainbow = true;
        break;
    default:
        break;
    }
}

int main(int argc, char *argv[])
{
    int colour_seen = -1;
    int opt;

    while ((opt = getopt(argc, argv,
                         ":abBcCfhlLnrosmxkVu:C:M:t:?")) != -1) {
        switch (opt) {
        case 'a':
            async_scroll = true;
            break;
        case 'b':
            if (bold != BOLD_ALL)
                bold = BOLD_RANDOM;
            break;
        case 'B':
            bold = BOLD_ALL;
            break;
        case 'c':
            japanese = true;
            break;
        case 'C': {
            static const char *names[] = {
                "green", "red", "blue", "white",
                "yellow", "cyan", "magenta", "black"
            };
            static const int values[] = {
                COLOR_GREEN, COLOR_RED, COLOR_BLUE, COLOR_WHITE,
                COLOR_YELLOW, COLOR_CYAN, COLOR_MAGENTA, COLOR_BLACK
            };
            int found = -1;
            for (int i = 0; i < 8; i++) {
                if (strcasecmp(optarg, names[i]) == 0) {
                    found = values[i];
                    break;
                }
            }
            if (found < 0) {
                fprintf(stderr,
                        " Invalid color selection\n"
                        " Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                return 0;
            }
            colour_seen = found;
            break;
        }
        case 'f':
            force_linux = true;
            break;
        case 'h':
            print_usage();
            return 0;
        case 'l':
            linux_mode = true;
            break;
        case 'L':
            lock_mode = true;
            break;
        case 'n':
            bold = BOLD_SPECIAL;
            break;
        case 'r':
            rainbow = true;
            break;
        case 'o':
            old_style = true;
            break;
        case 's':
            screensaver = true;
            break;
        case 'm':
            lambda_mode = true;
            break;
        case 'x':
            xwindow = true;
            break;
        case 'k':
            char_change = true;
            break;
        case 'V':
            print_version();
            return 0;
        case 'u':
            update_delay = atoi(optarg);
            break;
        case 'M':
            message = optarg;
            break;
        case 't':
            tty_name = optarg;
            break;
        case ':':
        case '?':
        default:
            print_usage();
            return 0;
        }
    }

    if (colour_seen >= 0)
        mcolour = colour_seen;

    if (lock_mode && message == NULL)
        message = "Computer locked.";

    /* Make sure rand() gives the same results for instances started
     * within the same second - observable behaviour of the original. */
    srand((unsigned int)time(NULL));

    if (force_linux) {
        char *term_env = getenv("TERM");
        if (term_env == NULL) {
            /* The reference program crashes in this obscure corner
             * (it copies the new type into the environment entry
             * it just looked up); preserve that failure mode. */
            char *nowhere = NULL;
            strcpy(nowhere, "linux");
        }
        setenv("TERM", "linux", 1);
    }

    if (tty_name != NULL) {
        tty_fp = fopen(tty_name, "r+");
        if (tty_fp == NULL) {
            fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n",
                    tty_name, strerror(errno));
            return 1;
        }
    }

    setlocale(LC_ALL, "");

    if (tty_fp != NULL) {
        SCREEN *screen = newterm(NULL, tty_fp, tty_fp);
        if (screen == NULL)
            return 1;
        set_term(screen);
    } else {
        if (initscr() == NULL)
            return 1;
    }
    curses_started = true;

    if (has_colors()) {
        start_color();
        use_default_colors();
        init_pair(PAIR_HEAD, COLOR_WHITE, -1);
        /* Pairs for the rainbow palette. */
        init_pair(PAIR_RAINBOW_BASE, COLOR_GREEN, -1);
        init_pair(PAIR_RAINBOW_BASE + 1, COLOR_YELLOW, -1);
        init_pair(PAIR_RAINBOW_BASE + 2, COLOR_BLUE, -1);
        init_pair(PAIR_RAINBOW_BASE + 3, COLOR_MAGENTA, -1);
        init_pair(PAIR_RAINBOW_BASE + 4, COLOR_CYAN, -1);
        set_colour(mcolour);
    }

    curs_set(0);
    noecho();
    cbreak();
    nodelay(stdscr, TRUE);

    signal(SIGTERM, term_handler);
    signal(SIGINT, stop_handler);
    signal(SIGQUIT, stop_handler);
    signal(SIGTSTP, stop_handler);
    if (lock_mode) {
        signal(SIGINT, SIG_IGN);
        signal(SIGQUIT, SIG_IGN);
        signal(SIGTSTP, SIG_IGN);
    }

    if (linux_mode) {
        fprintf(stderr,
                " Unable to use both \"setfont\" and \"consolechars\".\n");
        finish(0);
    }

    {
        int y, x;
        getmaxyx(stdscr, y, x);
        init_matrix(y, x);
    }

    unsigned long frame = 0;
    for (;;) {
        if (stop_requested)
            finish(0);

        int ch = getch();

        /* Re-read terminal size; curses processes SIGWINCH and
         * reports it through getch()/size changes. */
        {
            int y, x;
            getmaxyx(stdscr, y, x);
            if ((y != rows || x != cols) && y > 0 && x > 0) {
                init_matrix(y, x);
                clear();
            }
        }

        if (ch != ERR && ch != KEY_RESIZE) {
            if (screensaver)
                finish(0);
            handle_key(ch);
        }

        if (stop_requested)
            finish(0);

        if (!paused_now) {
            if (old_style) {
                update_old(frame);
                draw_old();
            } else {
                update_new(frame);
                draw_new();
            }
            draw_message();
            refresh();
        }

        frame++;

        long delay_ms = (long)update_delay * 10L;
        if (delay_ms > 0) {
            if (delay_ms > 2147483000L)
                delay_ms = 2147483000L;
            napms((int)delay_ms);
        }
    }
}
EOF
